import React from 'react';

import cn, { clsx } from 'clsx';

import { uniqueId } from '@helpers/unuqueId';

import styles from './styles.module.less';

interface IPohCardProps extends React.HTMLAttributes<HTMLDivElement> {
  header?: React.ReactNode;
  footer?: React.ReactNode;
  img?: string;
  subtitle?: React.ReactNode;
  text?: React.ReactNode;
  links?: React.ReactElement<any>[];
  bodyClassName?: string;
  footerClassName?: string;
}

const PohCard: React.FC<IPohCardProps> = ({
  className,
  header,
  footer,
  children,
  title,
  subtitle,
  text,
  links,
  img,
  bodyClassName,
  footerClassName,
  ...props
}) => {
  return (
    <div className={cn('card', className)} {...props}>
      {img && (
        <div
          className={clsx('card-img-top', styles.cardImg)}
          style={{ backgroundImage: `url(${img})` }}
        />
      )}
      {header && <div className="card-header">{header}</div>}
      <div className={cn('card-body', bodyClassName)}>
        {title && <h5 className="card-title">{title}</h5>}
        {subtitle && <h6 className="card-subtitle mb-2 text-muted">{subtitle}</h6>}
        {text && <p className="card-text">{text}</p>}
        {links &&
          links.map((link) =>
            React.cloneElement(link, { className: 'card-link', key: uniqueId('cardLink') }),
          )}
        {children}
      </div>
      {footer && <div className={cn('card-footer', footerClassName)}>{footer}</div>}
    </div>
  );
};

export default PohCard;
